const {tr,money,dateOnly:date,dateTime,errorText,days,number}=SuirenXI18n;
const root=document.querySelector('#app');
const productVersion=document.querySelector('meta[name="suirenx-version"]').content;
const toastNode=document.querySelector('#toast');
const state={token:sessionStorage.getItem('sx_token')||'',user:sessionStorage.getItem('sx_user')||'',admin:sessionStorage.getItem('sx_admin')==='true',page:location.hash.slice(1)||'home',owner:sessionStorage.getItem('sx_admin')==='true'?(sessionStorage.getItem('sx_owner')||''):'',assets:[],expiry:[],accounts:[],configs:[],tokens:[],audit:[],auditRetentionLimit:0,accountRegistrationEnabled:true,assetScope:'CURRENT',assetStatus:'ALL',assetSort:'purchase_date',expiryStatus:'ALL',expiryBucket:'ALL',expirySort:'actual_expiry_date',query:'',busy:false,loadError:'',loadedPages:new Set(),renderedPageKey:''};
const esc=(v='')=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api=async(path,opts={})=>{const headers=new Headers(opts.headers||{});if(state.token)headers.set('Authorization',`Bearer ${state.token}`);if(opts.body!==undefined)headers.set('Content-Type','application/json');const r=await fetch(path,{...opts,headers,body:opts.body===undefined?undefined:JSON.stringify(opts.body)});const type=r.headers.get('content-type')||'';const data=type.includes('json')?await r.json():await r.text();if(!r.ok){const e=new Error('request_failed');e.status=r.status;e.data=data;e.message=errorText(e);throw e}return data};
const key=()=>crypto.randomUUID();
function notify(message){toastNode.textContent=message;toastNode.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>toastNode.classList.remove('show'),2800)}
function logout(){modalRerender=null;state.token='';state.user='';state.admin=false;state.owner='';state.loadError='';state.loadedPages.clear();state.renderedPageKey='';sessionStorage.clear();location.hash='login';render()}
function navItem(id,label,icon){return `<button data-page="${id}" class="${state.page===id?'active':''}"><span class="nav-icon">${icon}</span>${label}</button>`}
function frame(title,body,sub=''){const name=state.user||tr('account.fallback');root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">${tr('brand.mark')}</span><span>${tr('brand.name')}<small>SUIRENX · WEB</small></span></div><div class="nav-label">${tr('nav.workspace')}</div><nav class="nav">${navItem('home',tr('nav.home'),'◫')}${navItem('assets',tr('nav.assets'),'▣')}${navItem('expiry',tr('nav.expiry'),'◇')}${navItem('conflicts',tr('nav.conflicts'),'△')}</nav>${state.admin?`<div class="nav-label">${tr('nav.admin')}</div><nav class="nav">${navItem('accounts',tr('nav.accounts'),'♙')}${navItem('configs',tr('nav.configs'),'⌁')}${navItem('tokens','API token','⌑')}${navItem('audit',tr('nav.audit'),'❏')}</nav>`:''}<div class="side-note">${tr('workspace.localNote')}</div><div class="profile"><span class="avatar">${esc(name.slice(0,1).toUpperCase())}</span><span class="profile-name">${esc(name)}<small>${state.admin?tr('account.roleAdmin'):tr('account.standard')}</small></span><button data-action="logout">${tr('action.logout')}</button></div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">${state.admin&&state.owner?(tr('workspace.ownerPrefix')+' ')+esc(ownerName()):'SuirenX / Web '+esc(productVersion)}</div><h1>${title}</h1></div><div class="top-actions">${languagePicker()}<span class="demo-tag">${tr('workspace.serverData')}</span><button class="btn mobile-menu" data-action="menu" aria-label="${tr('a11y.menu')}">☰</button>${state.admin&&['home','assets','expiry','conflicts'].includes(state.page)?workspaceSwitcher():''}</div></header>${sub?`<div class="notice" style="margin-bottom:16px">${sub}</div>`:''}${state.loadError?loadErrorNotice():''}${body}</main></div>`}
function ownerName(){return state.accounts.find(a=>a.id===state.owner)?.username||tr('workspace.adminSelf')}
function workspaceSwitcher(){const selected=state.accounts.find(a=>a.id===state.owner);const title=selected?.username||tr('workspace.adminSelf');return `<div class="workspace-switcher"><button class="workspace-trigger" type="button" data-action="toggle-workspaces" aria-haspopup="menu" aria-expanded="false"><span class="workspace-avatar">${esc(title.slice(0,1).toUpperCase())}</span><span class="workspace-current"><small>${tr('workspace.current')}</small><strong>${esc(title)}</strong></span><span class="workspace-chevron" aria-hidden="true">⌄</span></button><div class="workspace-menu" role="menu" aria-label="${tr('workspace.switch')}"><div class="workspace-menu-label">${tr('workspace.mine')}</div><button class="workspace-option ${state.owner?'':'selected'}" type="button" role="menuitemradio" aria-checked="${!state.owner}" data-action="workspace-owner" data-owner=""><span class="workspace-option-avatar">${esc((state.user||'S').slice(0,1).toUpperCase())}</span><span class="workspace-option-copy"><strong>${tr('workspace.adminSelf')}</strong><small>${esc(state.user||tr('account.superadmin'))}</small></span>${state.owner?'':'<span class="workspace-check" aria-hidden="true">✓</span>'}</button>${state.accounts.length?`<div class="workspace-menu-label workspace-other-label">${tr('workspace.others')}</div>${state.accounts.map(a=>{const active=state.owner===a.id;return `<button class="workspace-option ${active?'selected':''}" type="button" role="menuitemradio" aria-checked="${active}" data-action="workspace-owner" data-owner="${esc(a.id)}" ${a.disabled_at?'disabled aria-disabled="true"':''}><span class="workspace-option-avatar">${esc((a.username||'A').slice(0,1).toUpperCase())}</span><span class="workspace-option-copy"><strong>${esc(a.username)}</strong><small>${a.disabled_at?tr('account.disabledUnavailable'):tr('account.businessData')}</small></span>${active?'<span class="workspace-check" aria-hidden="true">✓</span>':''}</button>`}).join('')}`:''}</div></div>`}
function login(){root.innerHTML=`<main class="login-wrap"><section class="login-story"><div class="brand"><span class="brand-mark">${tr('brand.mark')}</span><span>${tr('brand.name')}<small>SUIRENX · WEB</small></span></div><h1>${tr('login.headlineFirst')}<br>${tr('login.headlineSecond')}</h1><p>${tr('login.story')}</p></section><section class="login-panel">${languagePicker()}<h2>${tr('login.title')}</h2><p>${tr('login.subtitle')}</p><div class="login-switch"><button class="active" data-login-mode="user">${tr('account.standard')}</button><button data-login-mode="admin">${tr('login.admin')}</button></div><form id="login-form"><label class="form-field">${tr('account.username')}<input class="field" name="username" autocomplete="username" required></label><label class="form-field">${tr('account.password')}<input class="field" name="password" type="password" autocomplete="current-password" required></label><button class="btn primary" type="submit">${tr('action.login')}</button><div id="login-error"></div></form><p style="margin-top:20px;font-size:11px">${tr('login.serverNote')}</p></section></main>`}
function loginMode(){return document.querySelector('[data-login-mode].active')?.dataset.loginMode||'user'}
async function loadAccounts(){if(!state.admin)return;state.accounts=(await api('/api/v1/admin/accounts')).accounts||[];if(state.owner&&!state.accounts.some(a=>a.id===state.owner)){state.owner='';sessionStorage.removeItem('sx_owner')}}
async function loadHome(){const [a,x]=await Promise.all([api('/api/v1/web/assets?scope=CURRENT'+(state.admin&&state.owner?`&owner_id=${encodeURIComponent(state.owner)}`:'')),api('/api/v1/web/expiry'+ownerQuery())]);state.assets=a.assets||[];state.expiry=x.items||[]}
function ownerQuery(){return state.admin&&state.owner?`?owner_id=${encodeURIComponent(state.owner)}`:''}
function metric(label,value,foot){return `<article class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></article>`}
function home(){const active=state.assets.filter(a=>a.status==='ACTIVE');const total=state.assets.reduce((n,a)=>n+Number(a.price_cents||0),0);const daily=active.reduce((n,a)=>n+Number(a.daily_cost_cents||0),0);const pending=state.expiry.filter(x=>['EXPIRED','DUE_TODAY','SOON'].includes(expiryBucket(x))).length;frame(tr('home.title'),`<div class="stack"><section class="metric-grid">${metric(tr('home.assetCount'),number(state.assets.length),tr('home.accountItems'))}${metric(tr('home.purchaseTotal'),money(total),tr('home.valueNote'))}${metric(tr('home.activeDailyCost'),money(daily),tr('home.rulesNote'))}${metric(tr('home.pendingExpiry'),number(pending),tr('home.expiryNote'))}</section><section class="two-col"><article class="card"><h2 class="card-title">${tr('home.continue')} <small>${tr('home.currentData')}</small></h2><div class="activity"><div class="activity-row"><i class="activity-dot"></i>${tr('asset.record')}<span>${tr('format.items',{count:state.assets.length,value:number(state.assets.length)})}</span></div><div class="activity-row"><i class="activity-dot"></i>${tr('nav.expiry')}<span>${tr('format.pending',{count:pending,value:number(pending)})}</span></div><div class="activity-row"><i class="activity-dot"></i>${tr('home.source')}<span>${tr('home.syncedData')}</span></div></div><div style="display:flex;gap:8px;margin-top:16px"><button class="btn primary" data-page="assets">${tr('home.openAssets')}</button><button class="btn" data-page="expiry">${tr('home.openExpiry')}</button></div></article><article class="card"><h2 class="card-title">${tr('home.boundaries')}</h2><div class="boundary"><strong>${tr('home.localTruth')}</strong>${tr('home.boundaryDescription')}<br><br>${tr('home.adminNote')}</div></article></section></div>`)}
function statusBadge(a){return `<span class="status ${a.archived_at?'warn':a.status==='ACTIVE'?'active':'muted'}">${a.archived_at?tr('status.archived'):a.status==='ACTIVE'?tr('asset.active'):tr('asset.retired')}</span>`}
function assetRows(){const q=state.query.trim().toLowerCase();const items=state.assets.filter(a=>(state.assetStatus==='ALL'||a.status===state.assetStatus)&&(!q||`${a.name} ${a.purchase_channel} ${(a.tags||[]).join(' ')}`.toLowerCase().includes(q))).sort((a,b)=>{const x=a[state.assetSort],y=b[state.assetSort];return typeof x==='number'&&typeof y==='number'?y-x:String(y||'').localeCompare(String(x||''))});if(!items.length)return `<div class="empty"><strong>${q?tr('empty.noMatches'):tr('asset.empty')}</strong>${q?tr('search.adjust'):tr('asset.emptyHint')}</div>`;return `<div class="table-wrap"><table><thead><tr><th>${tr('field.name')}</th><th>${tr('field.status')}</th><th>${tr('asset.purchaseDate')}</th><th>${tr('asset.purchaseCost')}</th><th>${tr('asset.dailyCost')}</th><th>${tr('asset.heldDays')}</th><th></th></tr></thead><tbody>${items.map(a=>`<tr><td><strong>${esc(a.name)}</strong><div class="subtext">${esc(a.purchase_channel||tr('asset.record'))} · ${(a.tags||[]).map(esc).join(tr('format.listSeparator'))}</div></td><td>${statusBadge(a)}</td><td>${date(a.purchase_date)}</td><td>${money(a.price_cents)}</td><td>${money(a.daily_cost_cents)}</td><td>${days(a.held_days)}</td><td><div class="row-actions">${a.archived_at?`<button class="btn small" data-action="restore-asset" data-id="${esc(a.id)}">${tr('action.restoreArchive')}</button>`:`<button class="btn small" data-action="edit-asset" data-id="${esc(a.id)}">${tr('action.viewEdit')}</button>`}<button class="btn small danger" data-action="delete-asset" data-id="${esc(a.id)}">${tr('action.delete')}</button></div></td></tr>`).join('')}</tbody></table></div>`}
function assets(){const body=`<section class="page-head"><div><h2>${tr('nav.assets')}</h2><p>${tr('asset.description')}</p></div><button class="btn primary" data-action="new-asset">${tr('asset.addButton')}</button></section><div class="toolbar"><input class="field" data-input="query" placeholder="${tr('asset.search')}" value="${esc(state.query)}"><select class="select" data-change="asset-scope"><option value="CURRENT" ${state.assetScope==='CURRENT'?'selected':''}>${tr('status.unarchived')}</option><option value="ARCHIVED" ${state.assetScope==='ARCHIVED'?'selected':''}>${tr('status.archived')}</option><option value="ALL" ${state.assetScope==='ALL'?'selected':''}>${tr('filter.allRecords')}</option></select><select class="select" data-change="asset-status"><option value="ALL">${tr('filter.allStatuses')}</option><option value="ACTIVE" ${state.assetStatus==='ACTIVE'?'selected':''}>${tr('asset.active')}</option><option value="RETIRED" ${state.assetStatus==='RETIRED'?'selected':''}>${tr('asset.retired')}</option></select><select class="select" data-change="asset-sort"><option value="purchase_date" ${state.assetSort==='purchase_date'?'selected':''}>${tr('sort.purchaseDate')}</option><option value="price_cents" ${state.assetSort==='price_cents'?'selected':''}>${tr('sort.purchaseCost')}</option><option value="daily_cost_cents" ${state.assetSort==='daily_cost_cents'?'selected':''}>${tr('sort.dailyCost')}</option><option value="held_days" ${state.assetSort==='held_days'?'selected':''}>${tr('sort.heldDays')}</option><option value="name" ${state.assetSort==='name'?'selected':''}>${tr('sort.name')}</option></select><button class="btn" data-action="refresh">${tr('action.refresh')}</button></div><article class="card">${assetRows()}</article>`;frame(tr('nav.assets'),body,tr('asset.archiveNote'))}
function actualExpiryDate(x){const dates=[x.package_expiry_date].filter(Boolean);if(x.opened_date&&Number(x.opened_validity_days)>0){const d=new Date(`${x.opened_date.slice(0,10)}T00:00:00Z`);d.setUTCDate(d.getUTCDate()+Number(x.opened_validity_days)-1);dates.push(d.toISOString().slice(0,10))}return dates.sort()[0]||''}
function dayDelta(dateValue){if(!dateValue)return null;const [y,m,d]=dateValue.slice(0,10).split('-').map(Number),now=new Date(),today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`,[ty,tm,td]=today.split('-').map(Number);return Math.round((Date.UTC(y,m-1,d)-Date.UTC(ty,tm-1,td))/86400000)}
function expiryBucket(x){if(x.archived_at||x.status!=='IN_USE')return 'INACTIVE';const days=dayDelta(actualExpiryDate(x));if(days===null)return 'NORMAL';if(days<0)return 'EXPIRED';if(days===0)return 'DUE_TODAY';if(days<=7)return 'SOON';return 'NORMAL'}
function expiryBucketLabel(x){const bucket=expiryBucket(x),count=dayDelta(actualExpiryDate(x));if(bucket==='INACTIVE')return x.archived_at?tr('status.archived'):tr('expiry.handled');if(count===null)return tr('expiry.noDate');if(bucket==='DUE_TODAY')return tr('expiry.today');return tr(bucket==='EXPIRED'?'expiry.expiredDays':bucket==='SOON'?'expiry.soonDays':'expiry.dueDays',{count:Math.abs(count),value:number(Math.abs(count))})}
function expiryRows(){const q=state.query.trim().toLowerCase();const items=state.expiry.filter(x=>(state.expiryStatus==='ALL'||x.status===state.expiryStatus)&&(state.expiryBucket==='ALL'||expiryBucket(x)===state.expiryBucket)&&(!q||`${x.name} ${x.category} ${x.location}`.toLowerCase().includes(q))).sort((a,b)=>{const x=state.expirySort==='actual_expiry_date'?actualExpiryDate(a):a[state.expirySort],y=state.expirySort==='actual_expiry_date'?actualExpiryDate(b):b[state.expirySort];return String(x||'').localeCompare(String(y||''))});if(!items.length)return `<div class="empty"><strong>${q?tr('expiry.noMatches'):tr('expiry.empty')}</strong>${q?tr('search.change'):tr('expiry.emptyHint')}</div>`;return `<div class="table-wrap"><table><thead><tr><th>${tr('expiry.item')}</th><th>${tr('expiry.bucket')}</th><th>${tr('expiry.useStatus')}</th><th>${tr('expiry.actualDate')}</th><th>${tr('expiry.packageDate')}</th><th>${tr('expiry.openedDate')}</th><th>${tr('expiry.openedValidity')}</th><th>${tr('expiry.location')}</th><th></th></tr></thead><tbody>${items.map(x=>`<tr><td><strong>${esc(x.name)}</strong><div class="subtext">${esc(x.category||tr('expiry.item'))}</div></td><td><span class="status ${expiryBucket(x)==='EXPIRED'||expiryBucket(x)==='DUE_TODAY'?'danger':expiryBucket(x)==='SOON'||expiryBucket(x)==='INACTIVE'?'warn':'active'}">${esc(expiryBucketLabel(x))}</span></td><td><span class="status ${x.archived_at?'warn':x.status==='IN_USE'?'active':'muted'}">${x.archived_at?tr('status.archived'):expiryStatus(x.status)}</span></td><td>${date(actualExpiryDate(x))}</td><td>${date(x.package_expiry_date)}</td><td>${date(x.opened_date)}</td><td>${x.opened_validity_days?days(x.opened_validity_days):'—'}</td><td>${esc(x.location||'—')}</td><td><div class="row-actions">${x.archived_at?`<button class="btn small" data-action="restore-expiry" data-id="${esc(x.id)}">${tr('action.restoreArchive')}</button>`:`<button class="btn small" data-action="edit-expiry" data-id="${esc(x.id)}">${tr('action.edit')}</button>`}<button class="btn small danger" data-action="delete-expiry" data-id="${esc(x.id)}">${tr('action.delete')}</button></div></td></tr>`).join('')}</tbody></table></div>`}
function expiryStatus(s){return ({IN_USE:tr('expiry.inUse'),USED_UP:tr('expiry.usedUp'),DISCARDED:tr('expiry.discarded')})[s]||s||tr('expiry.inUse')}
function expiry(){frame(tr('nav.expiry'),`<section class="page-head"><div><h2>${tr('nav.expiry')}</h2><p>${tr('expiry.description')}</p></div><button class="btn primary" data-action="new-expiry">${tr('expiry.addButton')}</button></section><div class="toolbar"><input class="field" data-input="query" placeholder="${tr('expiry.search')}" value="${esc(state.query)}"><select class="select" data-change="expiry-bucket"><option value="ALL">${tr('filter.allExpiry')}</option><option value="EXPIRED" ${state.expiryBucket==='EXPIRED'?'selected':''}>${tr('expiry.expired')}</option><option value="DUE_TODAY" ${state.expiryBucket==='DUE_TODAY'?'selected':''}>${tr('expiry.today')}</option><option value="SOON" ${state.expiryBucket==='SOON'?'selected':''}>${tr('expiry.withinWeek')}</option><option value="NORMAL" ${state.expiryBucket==='NORMAL'?'selected':''}>${tr('expiry.normal')}</option><option value="INACTIVE" ${state.expiryBucket==='INACTIVE'?'selected':''}>${tr('expiry.handledArchived')}</option></select><select class="select" data-change="expiry-status"><option value="ALL">${tr('filter.allUsage')}</option><option value="IN_USE" ${state.expiryStatus==='IN_USE'?'selected':''}>${tr('expiry.inUse')}</option><option value="USED_UP" ${state.expiryStatus==='USED_UP'?'selected':''}>${tr('expiry.usedUp')}</option><option value="DISCARDED" ${state.expiryStatus==='DISCARDED'?'selected':''}>${tr('expiry.discarded')}</option></select><select class="select" data-change="expiry-sort"><option value="actual_expiry_date" ${state.expirySort==='actual_expiry_date'?'selected':''}>${tr('sort.actualExpiry')}</option><option value="name" ${state.expirySort==='name'?'selected':''}>${tr('sort.name')}</option><option value="opened_date" ${state.expirySort==='opened_date'?'selected':''}>${tr('sort.openedDate')}</option></select><button class="btn" data-action="refresh">${tr('action.refresh')}</button></div><article class="card">${expiryRows()}</article>`,tr('expiry.note'))}
let modalRerender=null;
function closeModal(){document.querySelector('.modal-backdrop')?.remove();modalRerender=null}
function modal(title,desc,content){const old=document.querySelector('.modal-backdrop');old?.remove();root.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-header"><div><h2>${esc(title)}</h2><p>${esc(desc||'')}</p></div>${languagePicker()}<button class="icon-btn" data-action="close-modal" aria-label="${tr('action.close')}">×</button></header>${content}</section></div>`)}
const val=(f,k)=>f.elements[k]?.value?.trim()||'';
function assetForm(a={}){modalRerender=()=>assetForm(a);const editing=!!a.id;modal(editing?tr('asset.details'):tr('asset.add'),tr('asset.saveNote'),`<form id="asset-form" data-id="${esc(a.id||'')}" data-version="${esc(a.version||'')}"><input type="hidden" name="image_url" value="${esc(a.image_url||'')}"><input type="hidden" name="icon_key" value="${esc(a.icon_key||'')}"><div class="form-grid"><label class="form-field">${tr('field.name')}<input class="field" name="name" required maxlength="200" value="${esc(a.name||'')}"></label><label class="form-field">${tr('asset.costYuan')}<input class="field" name="price" type="number" min="0" step="0.01" required value="${a.price_cents!=null?(Number(a.price_cents)/100).toFixed(2):''}"></label><label class="form-field">${tr('asset.purchaseDate')}<input class="field" name="purchase_date" type="date" required value="${esc(a.purchase_date||'')}"></label><label class="form-field">${tr('asset.channelCategory')}<input class="field" name="purchase_channel" maxlength="120" value="${esc(a.purchase_channel||'')}"></label><label class="form-field">${tr('asset.lifecycle')}<select class="select" name="status"><option value="ACTIVE" ${a.status==='ACTIVE'?'selected':''}>${tr('asset.active')}</option><option value="RETIRED" ${a.status==='RETIRED'?'selected':''}>${tr('asset.retired')}</option></select></label><label class="form-field">${tr('asset.retiredDate')}<input class="field" name="retired_date" type="date" value="${esc(a.retired_date||'')}"></label><label class="form-field">${tr('asset.warrantyDate')}<input class="field" name="warranty_end_date" type="date" value="${esc(a.warranty_end_date||'')}"></label><label class="form-field">${tr('asset.tags')}<input class="field" name="tags" value="${esc((a.tags||[]).join(', '))}"></label><label class="form-field full">${tr('field.notes')}<textarea class="textarea" name="notes">${esc(a.notes||'')}</textarea></label><label class="form-field"><span>${tr('action.archive')}</span><select class="select" name="archived"><option value="false" ${!a.archived_at?'selected':''}>${tr('status.unarchived')}</option><option value="true" ${a.archived_at?'selected':''}>${tr('status.archived')}</option></select></label></div><div id="form-error"></div><div class="form-actions">${editing?`<button type="button" class="btn" data-action="toggle-retirement" data-id="${esc(a.id)}">${a.status==='ACTIVE'?tr('action.retire'):tr('action.reactivate')}</button>`:''}<button type="button" class="btn" data-action="close-modal">${tr('action.cancel')}</button><button class="btn primary" type="submit">${tr('action.saveRecord')}</button></div></form>`)}
function expiryForm(x={}){modalRerender=()=>expiryForm(x);const editing=!!x.id;modal(editing?tr('expiry.edit'):tr('expiry.add'),tr('expiry.formNote'),`<form id="expiry-form" data-id="${esc(x.id||'')}" data-version="${esc(x.version||'')}"><div class="form-grid"><label class="form-field">${tr('field.name')}<input class="field" name="name" required maxlength="200" value="${esc(x.name||'')}"></label><label class="form-field">${tr('field.category')}<input class="field" name="category" maxlength="100" value="${esc(x.category||'')}"></label><label class="form-field">${tr('expiry.packageDate')}<input class="field" name="package_expiry_date" type="date" value="${esc(x.package_expiry_date||'')}"></label><label class="form-field">${tr('expiry.openedDate')}<input class="field" name="opened_date" type="date" value="${esc(x.opened_date||'')}"></label><label class="form-field">${tr('expiry.validDays')}<input class="field" name="opened_validity_days" type="number" min="0" step="1" value="${Number(x.opened_validity_days||0)||''}"></label><label class="form-field">${tr('field.status')}<select class="select" name="status"><option value="IN_USE" ${x.status==='IN_USE'||!x.status?'selected':''}>${tr('expiry.inUse')}</option><option value="USED_UP" ${x.status==='USED_UP'?'selected':''}>${tr('expiry.usedUp')}</option><option value="DISCARDED" ${x.status==='DISCARDED'?'selected':''}>${tr('expiry.discarded')}</option></select></label><label class="form-field">${tr('expiry.optionalLocation')}<input class="field" name="location" value="${esc(x.location||'')}"></label><label class="form-field">${tr('action.archive')}<select class="select" name="archived"><option value="false" ${!x.archived_at?'selected':''}>${tr('status.unarchived')}</option><option value="true" ${x.archived_at?'selected':''}>${tr('status.archived')}</option></select></label><label class="form-field full">${tr('field.notes')}<textarea class="textarea" name="notes">${esc(x.notes||'')}</textarea></label></div><div id="form-error"></div><div class="form-actions"><button type="button" class="btn" data-action="close-modal">${tr('action.cancel')}</button><button class="btn primary" type="submit">${tr('action.saveRecord')}</button></div></form>`)}
async function conflicts(){frame(tr('nav.conflicts'),`<div class="stack"><article class="card"><h2 class="card-title">${tr('conflict.handling')}</h2><div class="notice">${tr('conflict.description')}</div><div style="margin-top:14px"><button class="btn primary" data-action="open-assets">${tr('action.viewAssets')}</button><button class="btn" data-action="open-expiry">${tr('action.viewExpiry')}</button></div></article><article class="card"><h2 class="card-title">${tr('conflict.accessible')}</h2><p class="muted" style="font-size:12px">${tr('conflict.queueNote')}</p></article></div>`)}
function accountsPage(){const rows=state.accounts.map(a=>`<tr><td><strong>${esc(a.username)}</strong><div class="subtext">${esc(a.id)}</div></td><td>${esc(a.role==='SUPERADMIN'?tr('account.roleAdmin'):a.role==='USER'?tr('account.roleUser'):a.role)}</td><td><span class="status ${a.disabled_at?'danger':'active'}">${a.disabled_at?tr('account.disabled'):tr('account.enabled')}</span></td><td>${date(a.created_at)}</td><td><div class="row-actions"><button class="btn small" data-action="account-data" data-id="${esc(a.id)}">${tr('account.viewData')}</button>${a.username!==state.user?`<button class="btn small" data-action="toggle-account" data-id="${esc(a.id)}" data-disabled="${!a.disabled_at}">${a.disabled_at?tr('account.enable'):tr('account.disable')}</button>`:''}</div></td></tr>`).join('');frame(tr('nav.accounts'),`<section class="page-head"><div><h2>${tr('account.management')}</h2><p>${tr('account.jwtNote')}</p></div><button class="btn" data-action="refresh">${tr('action.refresh')}</button></section><article class="card">${state.accounts.length?`<div class="table-wrap"><table><thead><tr><th>${tr('account.username')}</th><th>${tr('account.role')}</th><th>${tr('field.status')}</th><th>${tr('field.createdAt')}</th><th>${tr('field.actions')}</th></tr></thead><tbody>${rows}</tbody></table></div>`:('<div class="empty">'+tr('account.empty')+'</div>')}</article>`)}


const auditActionLabels=()=>({ACCOUNT_ENABLED:tr('account.enable'),ACCOUNT_DISABLED:tr('account.disable'),SUPERADMIN_PASSWORD_ROTATED:tr('audit.passwordRotated'),CONFIG_CREATED:tr('config.create'),CONFIG_UPDATED:tr('config.update'),CONFIG_DELETED:tr('config.delete'),API_TOKEN_CREATED:tr('token.issue'),API_TOKEN_UPDATED:tr('token.update'),API_TOKEN_REVOKED:tr('token.revoke'),CONFIG_SIZE_LIMIT_UPDATED:tr('audit.configLimit'),ACCOUNT_REGISTRATION_ENABLED:tr('registration.enable'),ACCOUNT_REGISTRATION_DISABLED:tr('registration.disable'),WEB_ASSET_CREATED:tr('audit.assetCreated'),WEB_ASSET_UPDATED:tr('audit.assetUpdated'),WEB_ASSET_DELETED:tr('audit.assetDeleted'),WEB_EXPIRY_CREATED:tr('expiry.add'),WEB_EXPIRY_UPDATED:tr('audit.expiryUpdated'),WEB_EXPIRY_DELETED:tr('audit.expiryDeleted')});
const auditTargetLabels=()=>({account:tr('account.username'),config:tr('nav.configs'),api_token:'API token',server_setting:tr('server.settings'),asset:tr('nav.assets'),expiry:tr('expiry.item')});
function auditTone(action){return /(_DELETED|_DISABLED|_REVOKED)$/.test(action)?'danger':/(_UPDATED|_ROTATED)$/.test(action)?'warn':'active'}
function auditRows(){const q=state.query.trim().toLowerCase();const items=state.audit.filter(e=>!q||`${e.actor_username||''} ${e.actor_id} ${e.action} ${auditActionLabels()[e.action]||''} ${auditTargetLabels()[e.target_type]||e.target_type} ${e.target_id}`.toLowerCase().includes(q));if(!items.length)return `<div class="empty"><strong>${q?tr('empty.noMatches'):tr('audit.empty')}</strong>${q?tr('search.changeKeywords'):tr('audit.emptyHint')}</div>`;return `<div class="table-wrap"><table><thead><tr><th>${tr('field.time')}</th><th>${tr('audit.actor')}</th><th>${tr('audit.action')}</th><th>${tr('audit.target')}</th><th>${tr('audit.rawAction')}</th></tr></thead><tbody>${items.map(e=>`<tr><td class="subtext">${esc(dateTime(e.created_at))}</td><td><strong>${esc(e.actor_username||e.actor_id||'—')}</strong>${e.actor_username?`<div class="subtext">${esc(e.actor_id)}</div>`:''}</td><td><span class="status ${auditTone(e.action)}">${esc(auditActionLabels()[e.action]||e.action)}</span></td><td>${esc(auditTargetLabels()[e.target_type]||e.target_type||'—')}<div class="subtext">${esc(e.target_id)}</div></td><td class="subtext">${esc(e.action)}</td></tr>`).join('')}</tbody></table></div>`}
function auditPage(){const limit=state.auditRetentionLimit;frame(tr('nav.audit'),`<section class="page-head"><div><h2>${tr('audit.title')}</h2><p>${tr('audit.description',{limit:limit?number(limit):'—'})}</p></div><button class="btn" data-action="refresh">${tr('action.refresh')}</button></section><div class="toolbar"><input class="field" data-input="query" placeholder="${tr('audit.search')}" value="${esc(state.query)}"></div><article class="card">${auditRows()}</article>`,tr('audit.note'))}
function pageKey(){return `${state.page}:${state.admin?(state.owner||state.user||'self'):'self'}`}
function loadErrorNotice(){return `<div class="notice error workspace-load-notice" role="alert"><strong>${tr('load.refreshFailed')}</strong><p>${esc(errorText(state.loadError))} ${tr('load.retained')}</p><button class="btn small" type="button" data-action="retry-load">${tr('action.retryLoad')}</button></div>`}
let workspaceView='page',initialLoadError=null;
function renderLoading(){workspaceView='loading';root.innerHTML=('<main class="loading" role="status">'+tr('load.loading')+'</main>')}
function renderInitialLoadError(error){workspaceView='error';initialLoadError=error;const message=errorText(error);frame(tr('load.unavailable'),`<section class="card workspace-load-error" role="alert"><h2>${tr('load.noData')}</h2><p>${tr('load.firstFailed')}</p><p class="muted">${esc(message)}</p><button class="btn primary" type="button" data-action="retry-load">${tr('action.retryLoad')}</button></section>`)}
function render(){workspaceView='page';if(!state.token||state.page==='login'){login();state.renderedPageKey='';return}const titles={home:tr('home.title'),assets:tr('nav.assets'),expiry:tr('nav.expiry'),conflicts:tr('nav.conflicts'),accounts:tr('nav.accounts'),configs:tr('nav.configs'),tokens:'API token',audit:tr('nav.audit')};if(!titles[state.page]||(!state.admin&&['accounts','configs','tokens','audit'].includes(state.page)))state.page='home';if(state.page==='home')home();else if(state.page==='assets')assets();else if(state.page==='expiry')expiry();else if(state.page==='conflicts')conflicts();else if(state.page==='accounts')accountsPage();else if(state.page==='configs')configsPage();else if(state.page==='tokens')tokensPage();else if(state.page==='audit')auditPage();state.renderedPageKey=pageKey()}
async function refresh(){if(!state.token){login();return}const key=pageKey();const preserve=state.loadedPages.has(key)&&state.renderedPageKey===key;state.loadError='';if(!preserve)renderLoading();else{const main=root.querySelector('.main');main?.setAttribute('aria-busy','true');if(main&&!main.querySelector('.workspace-refreshing'))main.querySelector('.topbar')?.insertAdjacentHTML('afterend',('<div class="notice workspace-refreshing" role="status">'+tr('load.refreshing')+'</div>'))}try{if(state.admin)await loadAccounts();if(state.page==='home')await loadHome();if(state.page==='assets'){const r=await api(`/api/v1/web/assets?scope=${state.assetScope}${ownerQuery()?`&owner_id=${encodeURIComponent(state.owner)}`:''}`);state.assets=r.assets||[]}if(state.page==='expiry')state.expiry=(await api('/api/v1/web/expiry'+ownerQuery())).items||[];if(state.page==='configs'){const [configs,registration]=await Promise.all([api('/api/v1/admin/configs'),api('/api/v1/admin/settings/account-registration')]);state.configs=configs.configs||[];state.accountRegistrationEnabled=registration.enabled}if(state.page==='tokens')state.tokens=(await api('/api/v1/admin/config-tokens')).tokens||[];if(state.page==='audit'){const r=await api('/api/v1/admin/audit-log');state.audit=r.entries||[];state.auditRetentionLimit=Number(r.retention_limit)||0}state.loadedPages.add(pageKey());state.loadError='';render()}catch(e){root.querySelector('.workspace-refreshing')?.remove();root.querySelector('.main')?.removeAttribute('aria-busy');if(e.status===401){handleError(e);return}const message=errorText(e);if(preserve){state.loadError=e;render()}else{state.loadError='';renderInitialLoadError(e)}}}
function handleError(e){if(e.status===401){logout();notify(tr('error.sessionExpired'));return}notify(errorText(e))}
function conflictForm(form,e,itemType,fd=new FormData(form)){if(e.status!==409||e.data?.code!=='version_conflict'||!e.data.remote){const box=form.querySelector('#form-error');if(box)showFormError(box,e);else notify(errorText(e));return}modalRerender=()=>conflictForm(form,e,itemType,fd);const remote=e.data.remote;const local=Object.fromEntries(fd);const localBody=itemType==='asset'?assetBody(form,fd):expiryBody(form,fd);modal(tr('conflict.found'),tr('conflict.review'),`<div class="conflict-cols"><section class="conflict-side"><h3>${tr('conflict.local')}</h3><pre class="token-secret">${esc(JSON.stringify(local,null,2))}</pre></section><section class="conflict-side"><h3>${tr('conflict.remotePrefix')}${esc(e.data.remote_version)}</h3><pre class="token-secret">${esc(JSON.stringify(remote,null,2))}</pre></section></div><div class="form-actions"><button class="btn" data-action="keep-remote">${tr('conflict.discardEdits')}</button><button class="btn primary" data-action="keep-local" data-type="${itemType}" data-id="${esc(form.dataset.id)}" data-remote-version="${esc(e.data.remote_version)}">${tr('conflict.keepEdits')}</button></div>`);state.pendingConflict={formData:local,type:itemType,id:form.dataset.id,body:localBody,remote,version:e.data.remote_version}}
function assetBody(form,fd=new FormData(form)){const retired=fd.get('status')==='RETIRED';const archived=fd.get('archived')==='true';return {name:val(form,'name'),price_cents:Math.round(Number(val(form,'price'))*100),purchase_date:val(form,'purchase_date'),status:val(form,'status'),retired_date:retired?(val(form,'retired_date')||new Date().toISOString().slice(0,10)):'',image_url:val(form,'image_url'),icon_key:val(form,'icon_key'),purchase_channel:val(form,'purchase_channel'),warranty_end_date:val(form,'warranty_end_date'),notes:val(form,'notes'),tags:val(form,'tags').split(',').map(s=>s.trim()).filter(Boolean),archived_at:archived?new Date().toISOString():''}}
function expiryBody(form,fd=new FormData(form)){return {name:val(form,'name'),category:val(form,'category'),package_expiry_date:val(form,'package_expiry_date'),opened_date:val(form,'opened_date'),opened_validity_days:Number(val(form,'opened_validity_days')||0),location:val(form,'location'),notes:val(form,'notes'),status:val(form,'status'),archived_at:fd.get('archived')==='true'?new Date().toISOString():''}}
function tokenBody(form,fd=new FormData(form)){return {label:val(form,'label'),transport_mode:val(form,'transport_mode'),config_keys:fd.getAll('config_keys'),expires_at:val(form,'expires_at')?new Date(val(form,'expires_at')).toISOString():''}}
async function saveAsset(form,baseVersion,body=assetBody(form),id=form.dataset.id){if(!id)await api('/api/v1/web/assets'+ownerQuery(),{method:'POST',headers:{'Idempotency-Key':key()},body});else await api(`/api/v1/web/assets/${encodeURIComponent(id)}${ownerQuery()}`,{method:'PUT',headers:{'Idempotency-Key':key()},body:{...body,base_version:Number(baseVersion)}});closeModal();notify(tr('asset.saved'));await refresh()}
async function saveExpiry(form,baseVersion,body=expiryBody(form),id=form.dataset.id){if(!id)await api('/api/v1/web/expiry'+ownerQuery(),{method:'POST',headers:{'Idempotency-Key':key()},body});else await api(`/api/v1/web/expiry/${encodeURIComponent(id)}${ownerQuery()}`,{method:'PUT',headers:{'Idempotency-Key':key()},body:{...body,base_version:Number(baseVersion)}});closeModal();notify(tr('expiry.saved'));await refresh()}
async function startLogin(form){const mode=loginMode(),err=document.querySelector('#login-error');err.innerHTML='';err._error=null;err.dataset.errorKey='';let data;try{data=await api(mode==='admin'?'/api/v1/admin/auth/login':'/api/v1/auth/login',{method:'POST',body:{username:val(form,'username'),password:val(form,'password')}})}catch(e){showFormError(err,e);return}state.token=data.access_token;state.user=val(form,'username');state.admin=mode==='admin';state.loadError='';state.loadedPages.clear();state.renderedPageKey='';sessionStorage.setItem('sx_token',state.token);sessionStorage.setItem('sx_user',state.user);sessionStorage.setItem('sx_admin',String(state.admin));state.page='home';location.hash='home';await refresh()}
async function openAsset(id){try{const a=await api(`/api/v1/web/assets/${encodeURIComponent(id)}${ownerQuery()}`);assetForm(a)}catch(e){handleError(e)}}
async function openExpiry(id){const x=state.expiry.find(i=>i.id===id);if(x)expiryForm(x)}
async function deleteRecord(type,id){const rows=type==='asset'?state.assets:state.expiry;const item=rows.find(x=>x.id===id);if(!item||!confirm(tr('delete.confirm',{name:item.name})))return;try{await api(`/api/v1/web/${type==='asset'?'assets':'expiry'}/${encodeURIComponent(id)}${ownerQuery()}`,{method:'DELETE',headers:{'Idempotency-Key':key()},body:{base_version:item.version}});notify(tr('delete.done'));await refresh()}catch(e){if(e.status===409&&e.data?.remote){showDeleteConflict(item,e,type,id)}else handleError(e)}}
async function restoreArchived(type,id){const item=(type==='asset'?state.assets:state.expiry).find(x=>x.id===id);if(!item)return;const route=type==='asset'?'assets':'expiry';const body=type==='asset'?{name:item.name,price_cents:item.price_cents,purchase_date:item.purchase_date,status:item.status,retired_date:item.retired_date||'',image_url:item.image_url||'',icon_key:item.icon_key||'',purchase_channel:item.purchase_channel||'',warranty_end_date:item.warranty_end_date||'',notes:item.notes||'',tags:item.tags||[],archived_at:''}:{name:item.name,category:item.category||'',package_expiry_date:item.package_expiry_date||'',opened_date:item.opened_date||'',opened_validity_days:item.opened_validity_days||0,location:item.location||'',notes:item.notes||'',status:item.status,archived_at:''};try{await api(`/api/v1/web/${route}/${encodeURIComponent(id)}${ownerQuery()}`,{method:'PUT',headers:{'Idempotency-Key':key()},body:{...body,base_version:item.version}});notify(tr('archive.restored'));await refresh()}catch(e){handleError(e)}}
async function toggleRetirement(id){const a=await api(`/api/v1/web/assets/${encodeURIComponent(id)}${ownerQuery()}`);const active=a.status!=='ACTIVE';const body={base_version:a.version,name:a.name,price_cents:a.price_cents,purchase_date:a.purchase_date,status:active?'ACTIVE':'RETIRED',retired_date:active?'':new Date().toISOString().slice(0,10),archived_at:a.archived_at||'',image_url:a.image_url||'',icon_key:a.icon_key||'',purchase_channel:a.purchase_channel||'',warranty_end_date:a.warranty_end_date||'',notes:a.notes||'',tags:a.tags||[]};try{await api(`/api/v1/web/assets/${encodeURIComponent(id)}${ownerQuery()}`,{method:'PUT',headers:{'Idempotency-Key':key()},body});closeModal();notify(active?tr('asset.reactivated'):tr('asset.retired'));await refresh()}catch(e){handleError(e)}}
async function fetchConfig(key){return api(`/api/v1/admin/configs/${encodeURIComponent(key)}`)}
function configForm(c={}){modalRerender=()=>configForm(c);modal(c.config_key?tr('config.edit'):tr('config.create'),tr('config.formNote'),`<form id="config-form" data-key="${esc(c.config_key||'')}"><div class="form-grid"><label class="form-field full">${tr('config.displayName')}<input class="field" name="display_name" required maxlength="120" value="${esc(c.display_name||'')}"></label><label class="form-field full">${tr('config.content')}<textarea class="textarea" style="min-height:320px;font-family:ui-monospace,monospace" name="content" spellcheck="false">${esc(c.content||'')}</textarea></label></div><div id="form-error"></div><div class="form-actions"><button type="button" class="btn" data-action="close-modal">${tr('action.cancel')}</button><button class="btn primary" type="submit">${tr('config.saveContent')}</button></div></form>`)}
function tokenForm(){modalRerender=()=>tokenForm();modal(tr('token.issue'),tr('token.formNote'),`<form id="token-form"><div class="form-grid"><label class="form-field full">${tr('field.name')}<input class="field" name="label" required maxlength="100" placeholder="${tr('token.labelExample')}"></label><label class="form-field">${tr('token.transport')}<select class="select" name="transport_mode"><option value="BEARER">Authorization: Bearer</option><option value="QUERY">${tr('token.queryMode')}</option></select></label><label class="form-field">${tr('token.optionalExpiry')}<input class="field" name="expires_at" type="datetime-local"></label><fieldset class="form-field full" style="border:1px solid var(--line);border-radius:10px;padding:12px"><legend>${tr('token.allowedConfigs')}</legend>${state.configs.filter(c=>!c.deleted_at).map(c=>`<label style="display:block;margin:7px 0"><input type="checkbox" name="config_keys" value="${esc(c.config_key)}"> ${esc(c.display_name)} <small class="muted">${esc(c.config_key)}</small></label>`).join('')||('<span class="muted">'+tr('config.createFirst')+'</span>')}</fieldset></div><div id="form-error"></div><div class="form-actions"><button type="button" class="btn" data-action="close-modal">${tr('action.cancel')}</button><button class="btn primary" type="submit">${tr('token.issueShow')}</button></div></form>`)}
async function showIssuedToken(t){state.tokens=(await api('/api/v1/admin/config-tokens')).tokens||[];tokensPage();issuedTokenModal(t)}
root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){state.page=b.dataset.page;state.query='';location.hash=state.page;await refresh();return}const act=b.dataset.action;try{if(act==='logout')logout();else if(act==='menu')root.querySelector('.shell')?.classList.toggle('menu-open');else if(act==='toggle-workspaces'){const wrap=b.closest('.workspace-switcher');const open=wrap.classList.toggle('open');b.setAttribute('aria-expanded',String(open))}else if(act==='workspace-owner'){state.owner=b.dataset.owner||'';if(state.owner)sessionStorage.setItem('sx_owner',state.owner);else sessionStorage.removeItem('sx_owner');await refresh()}else if(act==='refresh'||act==='retry-load')await refresh();else if(act==='new-asset')assetForm();else if(act==='edit-asset')await openAsset(b.dataset.id);else if(act==='delete-asset')await deleteRecord('asset',b.dataset.id);else if(act==='restore-asset')await restoreArchived('asset',b.dataset.id);else if(act==='new-expiry')expiryForm();else if(act==='edit-expiry')openExpiry(b.dataset.id);else if(act==='delete-expiry')await deleteRecord('expiry',b.dataset.id);else if(act==='restore-expiry')await restoreArchived('expiry',b.dataset.id);else if(act==='open-assets'){state.page='assets';location.hash='assets';await refresh()}else if(act==='open-expiry'){state.page='expiry';location.hash='expiry';await refresh()}else if(act==='close-modal'||(act==='backdrop'&&e.target===b))closeModal();else if(act==='toggle-retirement')await toggleRetirement(b.dataset.id);else if(act==='keep-remote'){const p=state.pendingConflict;closeModal();if(p){state.pendingConflict=null;if(p.type==='asset')await openAsset(p.id);else await openExpiry(p.id)}}else if(act==='keep-local'){const p=state.pendingConflict;if(!p)return;state.pendingConflict=null;closeModal();if(p.type==='asset')await saveAsset(null,p.version,p.body,p.id);else await saveExpiry(null,p.version,p.body,p.id)}else if(act==='cancel-conflict-delete'){state.pendingDelete=null;closeModal()}else if(act==='confirm-conflict-delete'){const p=state.pendingDelete;if(!p)return;state.pendingDelete=null;closeModal();await api(`/api/v1/web/${p.type==='asset'?'assets':'expiry'}/${encodeURIComponent(p.id)}${ownerQuery()}`,{method:'DELETE',headers:{'Idempotency-Key':key()},body:{base_version:Number(p.version)}});notify(tr('delete.done'));await refresh()}else if(act==='account-data'){state.owner=b.dataset.id;sessionStorage.setItem('sx_owner',state.owner);state.page='assets';location.hash='assets';await refresh()}else if(act==='toggle-account'){const disabled=b.dataset.disabled==='true';if(!confirm(disabled?tr('account.disableConfirm'):tr('account.enableConfirm')))return;await api(`/api/v1/admin/accounts/${encodeURIComponent(b.dataset.id)}/status`,{method:'PATCH',body:{disabled}});notify(disabled?tr('account.disabledDone'):tr('account.enabledDone'));await refresh()}else if(act==='new-config')configForm();else if(act==='edit-config')configForm(await fetchConfig(b.dataset.id));else if(act==='delete-config'){if(confirm(tr('config.deleteConfirm'))){await api(`/api/v1/admin/configs/${encodeURIComponent(b.dataset.id)}`,{method:'DELETE'});notify(tr('config.deleted'));await refresh()}}else if(act==='config-limit'){const d=await api('/api/v1/admin/settings/config-max-bytes');const raw=prompt(tr('config.maxBytes'),d.max_bytes);if(raw!==null){await api('/api/v1/admin/settings/config-max-bytes',{method:'PUT',body:{max_bytes:Number(raw)}});notify(tr('config.limitSaved'))}}else if(act==='new-token'){await refreshConfigsForToken()}else if(act==='revoke-token'){if(confirm(tr('token.revokeConfirm'))){await api(`/api/v1/admin/config-tokens/${encodeURIComponent(b.dataset.id)}`,{method:'DELETE'});notify(tr('token.revokedDone'));await refresh()}}else if(act==='copy-token'){await navigator.clipboard.writeText(document.querySelector('#issued-token').textContent);notify(tr('token.copied'))} }catch(err){handleError(err)}});
async function refreshConfigsForToken(){state.configs=(await api('/api/v1/admin/configs')).configs||[];tokenForm()}
root.addEventListener('change',async e=>{if(e.target.dataset.change==='asset-scope'){state.assetScope=e.target.value;await refresh()}if(e.target.dataset.change==='asset-status'){state.assetStatus=e.target.value;assets()}if(e.target.dataset.change==='asset-sort'){state.assetSort=e.target.value;assets()}if(e.target.dataset.change==='expiry-status'){state.expiryStatus=e.target.value;expiry()}if(e.target.dataset.change==='expiry-bucket'){state.expiryBucket=e.target.value;expiry()}if(e.target.dataset.change==='expiry-sort'){state.expirySort=e.target.value;expiry()}});
root.addEventListener('input',e=>{if(e.target.dataset.input==='query'){state.query=e.target.value;if(state.page==='assets')assets();else if(state.page==='expiry')expiry();else if(state.page==='audit')auditPage();const input=root.querySelector('[data-input="query"]');input?.focus();input?.setSelectionRange(state.query.length,state.query.length)}});
document.addEventListener('click',e=>{if(!e.target.closest('.workspace-switcher')){const wrap=root.querySelector('.workspace-switcher.open');wrap?.classList.remove('open');wrap?.querySelector('[data-action="toggle-workspaces"]')?.setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){const wrap=root.querySelector('.workspace-switcher.open');if(wrap){wrap.classList.remove('open');wrap.querySelector('[data-action="toggle-workspaces"]')?.setAttribute('aria-expanded','false')}}});
const pendingFormState=new WeakMap();
function setFormPending(form,pending){root.querySelectorAll('[data-change="language"]').forEach(picker=>picker.disabled=pending);if(!form?.isConnected)return;if(pending){if(form.dataset.pending==='true')return;const container=form.closest('.modal')||form;const controls=[...new Set(container.querySelectorAll('button,input,select,textarea'))];if(form.id==='login-form')controls.push(...document.querySelectorAll('[data-login-mode]'));const submit=form.querySelector('button[type="submit"]');pendingFormState.set(form,{controls:controls.map(control=>[control,control.disabled]),submit,label:submit?.textContent||''});form.dataset.pending='true';form.setAttribute('aria-busy','true');for(const control of controls)control.disabled=true;if(submit)submit.textContent=form.id==='login-form'?tr('pending.login'):form.id==='token-form'?tr('pending.issue'):tr('pending.save');return}const prior=pendingFormState.get(form);if(!prior)return;delete form.dataset.pending;form.removeAttribute('aria-busy');for(const [control,disabled] of prior.controls)if(control.isConnected)control.disabled=disabled;if(prior.submit?.isConnected)prior.submit.textContent=prior.label;pendingFormState.delete(form)}
root.addEventListener('submit',async e=>{const f=e.target;if(!['login-form','asset-form','expiry-form','config-form','token-form'].includes(f.id))return;e.preventDefault();if(f.dataset.pending==='true')return;const fd=new FormData(f);if(f.id==='token-form'&&!fd.getAll('config_keys').length){const box=f.querySelector('#form-error');if(box)showFormError(box,null,'validation.configRequired');return}const payload=f.id==='asset-form'?assetBody(f,fd):f.id==='expiry-form'?expiryBody(f,fd):f.id==='token-form'?tokenBody(f,fd):null;setFormPending(f,true);try{if(f.id==='login-form'){await startLogin(f);return}if(f.id==='asset-form'){await saveAsset(f,Number(f.dataset.version),payload);return}if(f.id==='expiry-form'){await saveExpiry(f,Number(f.dataset.version),payload);return}if(f.id==='config-form'){const k=f.dataset.key;const body={display_name:val(f,'display_name'),content:val(f,'content')};await api(k?`/api/v1/admin/configs/${encodeURIComponent(k)}`:'/api/v1/admin/configs',{method:k?'PUT':'POST',body});closeModal();notify(tr('config.saved'));await refresh();return}if(f.id==='token-form'){const token=await api('/api/v1/admin/config-tokens',{method:'POST',body:payload});await showIssuedToken(token);return}}catch(err){if((f.id==='asset-form'||f.id==='expiry-form')&&err.status===409){conflictForm(f,err,f.id==='asset-form'?'asset':'expiry',fd);return}const box=f.querySelector('#form-error')||f.querySelector('#login-error');if(box)showFormError(box,err);else handleError(err)}finally{setFormPending(f,false)}});
root.addEventListener('click',e=>{const b=e.target.closest('[data-login-mode]');if(b){document.querySelectorAll('[data-login-mode]').forEach(x=>x.classList.toggle('active',x===b))}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1)||'home';if(p==='login'){logout();return}state.page=p;refresh()});

function configReadPath(configKey){return '/api/v1/configs/'+encodeURIComponent(configKey)+'/content'}
function configsPage(){
  const rows=state.configs.map(c=>{
    const readPath=c.deleted_at?('<span class="subtext">'+tr('config.deletedUnreadable')+'</span>'):'<div class="config-read-path">GET '+esc(configReadPath(c.config_key))+'</div><button class="btn small" data-action="copy-config-path" data-path="'+esc(configReadPath(c.config_key))+('">'+tr('config.copyPath')+'</button>');
    return '<tr><td><strong>'+esc(c.display_name)+'</strong><div class="subtext">'+esc(c.config_key)+'</div>'+readPath+'</td><td>'+(c.deleted_at?('<span class="status danger">'+tr('status.deleted')+'</span>'):('<span class="status active">'+tr('config.readable')+'</span>'))+'</td><td>'+date(c.updated_at)+'</td><td><div class="row-actions"><button class="btn small" data-action="edit-config" data-id="'+esc(c.config_key)+('">'+tr('config.editView')+'</button>')+(c.deleted_at?'':'<button class="btn small danger" data-action="delete-config" data-id="'+esc(c.config_key)+('">'+tr('action.delete')+'</button>'))+'</div></td></tr>'
  }).join('');
  const enabled=state.accountRegistrationEnabled===true;
  frame(tr('nav.configs'),('<section class="page-head"><div><h2>'+tr('nav.configs')+'</h2><p>'+tr('config.description')+'</p></div><button class="btn primary" data-action="new-config">'+tr('config.addButton')+'</button></section><section class="card server-setting-card"><div><h2 class="card-title">'+tr('server.configuration')+'</h2><strong>'+tr('registration.allowed')+'</strong><p class="subtext">')+(enabled?tr('registration.enabledNote'):tr('registration.disabledNote'))+'</p></div><button type="button" class="registration-switch" role="switch" aria-checked="'+(enabled?'true':'false')+'" data-action="toggle-registration"><span class="registration-track"><span></span></span><span>'+(enabled?tr('status.on'):tr('status.off'))+'</span></button></section><article class="card">'+(state.configs.length?('<div class="table-wrap"><table><thead><tr><th>'+tr('config.filePath')+'</th><th>'+tr('field.status')+'</th><th>'+tr('field.updatedAt')+'</th><th></th></tr></thead><tbody>')+rows+'</tbody></table></div>':('<div class="empty"><strong>'+tr('config.empty')+'</strong>'+tr('config.emptyHint')+'</div>'))+('</article><div class="config-page-actions"><button class="btn" data-action="config-limit">'+tr('config.adjustLimit')+'</button></div>'))
}
function tokensPage(){
  const rows=state.tokens.map(t=>{
    const revoked=!!t.revoked_at;
    const expired=!revoked&&t.expires_at&&new Date(t.expires_at)<new Date();
    const actions=revoked?'—':'<button class="btn small" data-action="edit-token" data-id="'+esc(t.id)+('">'+tr('action.edit')+'</button><button class="btn small danger" data-action="revoke-token" data-id="')+esc(t.id)+('">'+tr('action.revoke')+'</button>');
    return '<tr><td><strong>'+esc(t.label)+'</strong><div class="subtext">'+esc(t.id)+'</div></td><td>'+esc(t.transport_mode)+'</td><td>'+(t.config_keys||[]).map(esc).join('<br>')+'</td><td>'+(revoked?('<span class="status danger">'+tr('token.revoked')+'</span>'):expired?('<span class="status warn">'+tr('expiry.expired')+'</span>'):('<span class="status active">'+tr('token.valid')+'</span>'))+'</td><td>'+date(t.created_at)+('<div class="subtext">'+tr('token.expiresPrefix'))+date(t.expires_at)+'</div></td><td>'+date(t.last_used_at)+'</td><td><div class="row-actions">'+actions+'</div></td></tr>'
  }).join('');
  frame('API token',('<section class="page-head"><div><h2>'+tr('token.restricted')+'</h2><p>'+tr('token.description')+'</p></div><button class="btn primary" data-action="new-token">'+tr('token.issueButton')+'</button></section><article class="card">')+(state.tokens.length?('<div class="table-wrap"><table class="token-table"><thead><tr><th>'+tr('field.name')+'</th><th>'+tr('token.transport')+'</th><th>'+tr('token.configs')+'</th><th>'+tr('field.status')+'</th><th>'+tr('token.issuedExpires')+'</th><th>'+tr('token.lastUsed')+'</th><th></th></tr></thead><tbody>')+rows+'</tbody></table></div>':('<div class="empty"><strong>'+tr('token.empty')+'</strong>'+tr('token.emptyHint')+'</div>'))+('</article><div class="notice" style="margin-top:14px">'+tr('token.queryWarning')+'</div>'))
}
function tokenEditForm(token){modalRerender=()=>tokenEditForm(token);
  if(!token||token.revoked_at){notify(tr('token.revokedEdit'));return}
  const allowed=new Set(token.config_keys||[]);
  const configs=state.configs.filter(c=>!c.deleted_at);
  modal(tr('token.edit'),tr('token.editNote'), '<form id="token-edit-form" data-id="'+esc(token.id)+('"><div class="form-grid"><label class="form-field full">'+tr('field.name')+'<input class="field" name="label" required maxlength="100" value="')+esc(token.label)+('"></label><fieldset class="form-field full" style="border:1px solid var(--line);border-radius:10px;padding:12px"><legend>'+tr('token.requiredConfigs')+'</legend>')+(configs.map(c=>'<label class="token-config-option"><input type="checkbox" name="config_keys" value="'+esc(c.config_key)+'" '+(allowed.has(c.config_key)?'checked':'')+'> '+esc(c.display_name)+' <small class="muted">'+esc(c.config_key)+'</small></label>').join('')||('<span class="muted">'+tr('config.noneAvailable')+'</span>'))+('</fieldset><div class="notice full">'+tr('token.noSecretChange')+'</div></div><div id="form-error"></div><div class="form-actions"><button type="button" class="btn" data-action="close-modal">'+tr('action.cancel')+'</button><button class="btn primary" type="submit">'+tr('token.savePermissions')+'</button></div></form>'))
}
root.addEventListener('click',async e=>{
  const b=e.target.closest('button[data-action]');if(!b)return;
  try{
    if(b.dataset.action==='copy-config-path'){
      const path=b.dataset.path;
      try{await navigator.clipboard.writeText(path);notify(tr('config.pathCopied'))}catch(_){notify(tr('config.clipboardFailed'))}
    }else if(b.dataset.action==='toggle-registration'){
      const result=await api('/api/v1/admin/settings/account-registration',{method:'PUT',body:{enabled:!state.accountRegistrationEnabled}});
      state.accountRegistrationEnabled=result.enabled;render();notify(result.enabled?tr('registration.enabledDone'):tr('registration.disabledDone'))
    }else if(b.dataset.action==='edit-token'){
      state.configs=(await api('/api/v1/admin/configs')).configs||[];
      tokenEditForm(state.tokens.find(t=>t.id===b.dataset.id))
    }
  }catch(err){handleError(err)}
});
root.addEventListener('submit',async e=>{
  const f=e.target;if(f.id!=='token-edit-form')return;e.preventDefault();
  if(f.dataset.pending==='true')return;
  const formData=new FormData(f);
  const keys=Array.from(formData.getAll('config_keys'));
  const label=formData.get('label')?.trim()||'';
  const box=f.querySelector('#form-error');
  if(!label||!keys.length){if(box)showFormError(box,null,!label?'validation.nameRequired':'validation.permissionRequired');return}
  setFormPending(f,true);try{
    await api('/api/v1/admin/config-tokens/'+encodeURIComponent(f.dataset.id),{method:'PUT',body:{label,config_keys:keys}});
    closeModal();notify(tr('token.permissionsSaved'));await refresh()
  }catch(err){if(box)showFormError(box,err);else handleError(err)}finally{setFormPending(f,false)}
});



function showDeleteConflict(item,e,type,id){modalRerender=()=>showDeleteConflict(item,e,type,id);modal(tr('conflict.changed'),tr('conflict.deleteReview'),`<div class="conflict-cols"><section class="conflict-side"><h3>${tr('delete.pending')}</h3><p>${esc(item.name)}</p></section><section class="conflict-side"><h3>${tr('conflict.remotePrefix')}${esc(e.data.remote_version)}</h3><pre class="token-secret">${esc(JSON.stringify(e.data.remote,null,2))}</pre></section></div><div class="form-actions"><button class="btn" data-action="cancel-conflict-delete">${tr('conflict.keepRemote')}</button><button class="btn danger" data-action="confirm-conflict-delete" data-type="${type}" data-id="${esc(id)}" data-version="${esc(e.data.remote_version)}">${tr('conflict.deleteRemote')}</button></div>`);state.pendingDelete={type,id,version:e.data.remote_version}}

function issuedTokenModal(t){modalRerender=()=>issuedTokenModal(t);modal(tr('token.copyNow'),tr('token.onceNote'),`<div class="token-secret" id="issued-token">${esc(t.token)}</div><p style="margin-top:12px;font-size:12px">${tr('token.configsPrefix')}${(t.config_keys||[]).map(esc).join(tr('format.listSeparator'))||'—'}</p><div class="form-actions"><button class="btn primary" data-action="copy-token">${tr('token.copy')}</button><button class="btn" data-action="close-modal">${tr('token.saved')}</button></div>`)}

function languagePicker(){const preference=SuirenXI18n.preference,browserLanguage=SuirenXI18n.matchLanguage(navigator.languages?.length?navigator.languages:[navigator.language]);return `<label class="language-picker"><span>${tr('language.title')}</span><select class="select" data-change="language" aria-label="${tr('language.title')}"><option value="" ${preference===''?'selected':''}>${tr('language.system')} · ${browserLanguage==='en'?'English':'简体中文'}</option><option value="zh-Hans" ${preference==='zh-Hans'?'selected':''}>简体中文</option><option value="en" ${preference==='en'?'selected':''}>English</option></select></label>`}
function showFormError(box,error,key=''){box._error=error;box.dataset.errorKey=key;box.innerHTML=`<div class="notice error" style="margin-top:12px">${esc(key?tr(key):errorText(error))}</div>`}
function switchLanguage(preference){
  if(root.querySelector('form[data-pending="true"]'))return;
  const controls=[...root.querySelectorAll('input,textarea,select')].filter(control=>control.dataset.change!=='language');
  const drafts=controls.map(control=>({value:control.value,checked:control.checked,disabled:control.disabled,scrollTop:control.scrollTop,scrollLeft:control.scrollLeft}));
  const focus=controls.indexOf(document.activeElement);
  const selection=focus>=0?[controls[focus].selectionStart,controls[focus].selectionEnd]:null;
  const errors=[...root.querySelectorAll('#form-error,#login-error')].map(box=>({id:box.id,error:box._error,key:box.dataset.errorKey}));
  const mode=loginMode(),hadModal=!!root.querySelector('.modal-backdrop'),menuOpen=!!root.querySelector('.menu-open'),workspaceOpen=!!root.querySelector('.workspace-switcher.open');
  const pendingConflict=state.pendingConflict,pendingDelete=state.pendingDelete;
  const modalScroll=root.querySelector('.modal')?.scrollTop||0,scroll=[window.scrollX,window.scrollY];
  SuirenXI18n.setPreference(preference);
  if(workspaceView==='loading')renderLoading();else if(workspaceView==='error')renderInitialLoadError(initialLoadError);else render();
  if(hadModal&&modalRerender)modalRerender();
  state.pendingConflict=pendingConflict;state.pendingDelete=pendingDelete;
  const updated=[...root.querySelectorAll('input,textarea,select')].filter(control=>control.dataset.change!=='language');
  updated.forEach((control,index)=>{const draft=drafts[index];if(!draft)return;control.value=draft.value;control.checked=draft.checked;control.disabled=draft.disabled;control.scrollTop=draft.scrollTop;control.scrollLeft=draft.scrollLeft});
  for(const saved of errors){const box=root.querySelector('#'+saved.id);if(box&&(saved.error||saved.key))showFormError(box,saved.error,saved.key)}
  root.querySelectorAll('[data-login-mode]').forEach(button=>button.classList.toggle('active',button.dataset.loginMode===mode));
  if(menuOpen)root.querySelector('.shell')?.classList.add('menu-open');
  if(workspaceOpen){const workspace=root.querySelector('.workspace-switcher');workspace?.classList.add('open');workspace?.querySelector('.workspace-trigger')?.setAttribute('aria-expanded','true')}
  if(hadModal){const dialog=root.querySelector('.modal');if(dialog)dialog.scrollTop=modalScroll}
  if(focus>=0&&updated[focus]){updated[focus].focus({preventScroll:true});if(selection?.[0]!=null)try{updated[focus].setSelectionRange(...selection)}catch(_){}}
  window.scrollTo(...scroll);
}
root.addEventListener('change',event=>{if(event.target.dataset.change==='language')switchLanguage(event.target.value)});
window.addEventListener('languagechange',()=>{if(!SuirenXI18n.preference)switchLanguage('')});

(async()=>{if(state.token){await refresh()}else{state.page='login';login()}})();
